"""Article-specific editorial source for CC-09 (Civil Code arts. 671-700)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {
        "target": target,
        "o_que_diz": says,
        "o_que_significa": means,
        "exemplo_pratico": example,
        "atencao": warning,
        "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}],
    }


ROWS = {
    "671": row("Se o mandatário usa recursos ou crédito do mandante para adquirir em nome próprio o bem que deveria comprar para ele, o mandante pode exigir judicialmente a entrega.", "A regra impede que o representante se aproprie da oportunidade confiada. A designação expressa da compra no mandato e a disponibilidade de fundos ou crédito ligam a aquisição ao interesse do mandante.", "Procurador recebe dinheiro para comprar uma máquina indicada, mas registra a compra em seu próprio nome; o mandante exige a transferência.", "A ação pressupõe correspondência entre a compra realizada e a incumbência expressa. Eventuais perdas adicionais dependem de prova.", "Ação de entrega", "medida judicial destinada a obter a coisa adquirida indevidamente pelo mandatário"),
    "672": row("Havendo vários mandatários no mesmo instrumento, cada um pode agir separadamente, salvo se os poderes forem conjuntos, repartidos por atos ou organizados em sequência. A atuação conjunta incompleta pode ser ratificada.", "A regra supletiva é de atuação individual. O texto do mandato pode exigir participação de todos, distribuir tarefas ou condicionar um ato ao anterior; nessas hipóteses, a eficácia acompanha a organização escolhida.", "Dois procuradores recebem poderes conjuntos para vender imóvel; a assinatura de apenas um não basta, salvo posterior ratificação.", "Ratificação posterior retroage, mas não deve ser presumida. É indispensável ler como os poderes foram distribuídos.", "Mandatários conjuntos", "procuradores que devem atuar em conjunto por determinação do instrumento"),
    "673": row("Terceiro que conhece os limites da procuração e mesmo assim contrata além deles não pode cobrar do mandatário, salvo se este prometeu obter ratificação ou assumiu responsabilidade pessoal.", "Quem negocia sabendo do excesso aceita o risco de o mandante não ficar vinculado. A responsabilidade do procurador surge apenas das garantias específicas que ele próprio ofereceu.", "Comprador conhece o limite de preço da procuração, aceita negócio diferente e depois não pode exigir indenização do procurador que nada garantiu.", "A regra depende da ciência do terceiro. Se o mandatário ocultou a insuficiência de poderes, outras consequências podem ser aplicáveis.", "Exorbitância", "atuação que ultrapassa os poderes conferidos pelo mandato"),
    "674": row("Mesmo sabendo da morte, interdição ou mudança de estado do mandante, o mandatário deve terminar negócio já iniciado quando a demora puder causar perigo.", "A extinção ou alteração subjetiva do mandato não autoriza abandono imediato de providência urgente. O dever excepcional protege o patrimônio ou o interesse envolvido até que outra pessoa possa agir.", "Procurador conclui medida urgente para impedir perda de prazo após saber da morte do mandante.", "A autorização é conservatória e ligada ao perigo da demora; não permite iniciar livremente novos negócios após a causa extintiva.", "Perigo na demora", "risco de dano decorrente do adiamento de uma providência necessária"),
    "675": row("O mandante deve cumprir as obrigações que o mandatário assumiu dentro dos poderes recebidos e, quando solicitado, adiantar os valores necessários à execução da incumbência.", "Atos regulares do representante vinculam o mandante perante terceiros. Além disso, o mandatário não precisa financiar pessoalmente despesas indispensáveis se pedir antecipação.", "Empresa adianta ao procurador as custas necessárias e paga obrigação contratada por ele dentro da autorização.", "Obrigações fora dos poderes não são automaticamente assumidas pelo mandante. A necessidade e o vínculo das despesas com a tarefa devem ser demonstrados.", "Adiantamento", "entrega antecipada de recursos para custear a execução do mandato"),
    "676": row("O mandante paga a remuneração combinada e reembolsa as despesas da execução, mesmo que o resultado esperado não ocorra, salvo quando o insucesso decorrer de culpa do mandatário.", "O mandato remunerado normalmente paga a atividade diligente, não a garantia de sucesso. O risco do resultado permanece com o mandante, mas a culpa do procurador afasta a proteção legal.", "Corretor mandatário realiza todas as diligências autorizadas, porém a operação fracassa por fato externo; recebe o ajustado e recupera os gastos.", "Deve-se distinguir simples insucesso de execução culposa. O contrato também pode estabelecer condições legítimas para a remuneração.", "Remuneração ajustada", "pagamento definido pelas partes pelo desempenho do mandato"),
    "677": row("Valores que o mandatário adianta para cumprir o mandato geram juros em seu favor desde cada desembolso.", "O representante que financia a incumbência tem crédito não apenas pelo principal, mas também pelos juros a partir do momento em que utilizou recursos próprios.", "Procurador paga taxa necessária em 10 de março; o reembolso inclui juros contados dessa data.", "A despesa deve estar vinculada à execução do mandato. Taxa, cálculo e eventual convenção precisam observar o regime jurídico aplicável.", "Desembolso", "saída efetiva de dinheiro para pagar uma despesa"),
    "678": row("O mandante deve indenizar perdas sofridas pelo mandatário durante a execução, desde que não resultem de culpa do próprio mandatário nem de excesso de poderes.", "O risco de dano inerente ao cumprimento regular da incumbência recai sobre quem a confiou. A proteção desaparece quando o representante causa o prejuízo ou atua além da autorização.", "Mandatário sofre gasto extraordinário inevitável ao proteger bem do mandante e pede ressarcimento.", "Não basta o dano coincidir no tempo com o mandato; é necessário vínculo com a execução regular e ausência das causas excludentes indicadas.", "Ressarcimento", "reposição patrimonial de gasto ou perda suportada por outra pessoa"),
    "679": row("Se o mandatário desobedece instruções internas, mas permanece dentro dos poderes externos, o mandante continua obrigado perante terceiros e pode cobrar do mandatário os danos causados.", "O artigo separa poderes de representação e orientações internas. O terceiro pode confiar no alcance da procuração, enquanto o descumprimento das instruções é resolvido entre mandante e mandatário.", "Procuração autoriza venda à vista, mas instrução interna recomenda certa data; realizada antes, a venda vincula o mandante, que cobra prejuízos do procurador.", "Se houver excesso dos poderes conferidos, o regime muda. Também importa verificar a boa-fé e o conhecimento do terceiro.", "Instrução interna", "orientação do mandante que disciplina a execução sem necessariamente limitar poderes perante terceiros"),
    "680": row("Quando várias pessoas concedem mandato para negócio comum, todas respondem solidariamente perante o mandatário pelos compromissos e efeitos da incumbência, preservado o regresso entre elas.", "O mandatário pode cobrar o total de qualquer mandante. Quem paga além da própria parte pode buscar dos demais a parcela correspondente.", "Três coproprietários nomeiam procurador para negócio comum; um deles reembolsa todas as despesas e depois cobra as quotas dos outros.", "A solidariedade exige mandato plural para interesse comum. O direito regressivo não reduz a proteção externa do mandatário.", "Direito regressivo", "pretensão de recuperar dos coobrigados a parte paga por conta deles"),
    "681": row("O mandatário pode reter a coisa que possui por causa do mandato até ser reembolsado das despesas realizadas no cumprimento da incumbência.", "A retenção funciona como garantia do crédito diretamente ligado à execução. O representante conserva a coisa temporariamente, sem adquirir sua propriedade.", "Procurador mantém documentos e bem recebido no mandato até o pagamento dos gastos necessários comprovados.", "O crédito deve decorrer do encargo e a retenção precisa recair sobre coisa legitimamente possuída em razão dele. Não autoriza apropriação definitiva.", "Direito de retenção", "faculdade de conservar uma coisa até o pagamento de crédito relacionado a ela"),
    "682": row("O mandato termina por revogação ou renúncia, morte ou interdição de uma das partes, mudança de estado incapacitante, fim do prazo ou conclusão do negócio.", "A lei reúne causas ligadas à vontade, à pessoa e ao esgotamento da finalidade. Outros artigos preservam certos efeitos para terceiros de boa-fé e situações urgentes.", "Procuração para vender um veículo cessa quando a venda é concluída ou quando chega a data final estabelecida.", "A extinção não desfaz automaticamente atos anteriores. Cláusulas de irrevogabilidade, mandato em causa própria e proteção de terceiros recebem disciplina especial.", "Revogação", "ato pelo qual o mandante retira os poderes anteriormente concedidos"),
    "683": row("Se o mandato declarado irrevogável for revogado pelo mandante, ele deve reparar as perdas e os danos causados.", "Nesta hipótese, a revogação produz a ruptura, mas gera responsabilidade pelo descumprimento da cláusula de estabilidade.", "Mandante revoga procuração com cláusula de irrevogabilidade e indeniza o mandatário pelos prejuízos comprovados.", "Não se confunde com as hipóteses seguintes, em que a revogação pode ser juridicamente ineficaz. A indenização exige dano e nexo causal.", "Irrevogabilidade", "cláusula que restringe a retirada unilateral dos poderes"),
    "684": row("A revogação não produz efeito quando a irrevogabilidade integra negócio bilateral ou foi estabelecida exclusivamente em benefício do mandatário.", "Nesses casos, a estabilidade dos poderes protege uma relação ou interesse próprio que não pode ser desfeito unilateralmente pelo mandante.", "Procuração irrevogável integra contrato com prestações recíprocas; tentativa isolada de retirá-la não afeta os poderes.", "É necessário demonstrar a vinculação ao negócio bilateral ou o interesse exclusivo do mandatário. A mera palavra 'irrevogável' pode conduzir ao regime indenizatório do artigo anterior.", "Ineficácia", "falta de produção do efeito jurídico pretendido por determinado ato"),
    "685": row("No mandato em causa própria, a revogação é ineficaz e a morte das partes não encerra os poderes. O mandatário não presta contas e pode transferir a si os bens abrangidos, cumpridas as formalidades legais.", "A cláusula atende interesse próprio do mandatário e aproxima o instrumento da execução de uma posição patrimonial já atribuída, por isso recebe regime excepcional.", "Titular concede mandato em causa própria sobre imóvel; o mandatário pode formalizar a transferência mesmo após a morte do mandante.", "A cláusula não dispensa escritura, registro ou outras formas exigidas para o bem. Seu alcance deve ser expresso e não se presume.", "Em causa própria", "mandato conferido também no interesse patrimonial do mandatário, com efeitos especiais"),
    "686": row("Revogação comunicada apenas ao mandatário não prejudica terceiros que, sem conhecê-la e de boa-fé, ainda contratam com ele. O mandante conserva pretensões contra o procurador. Certos poderes ligados a negócios já iniciados são irrevogáveis.", "A publicidade insuficiente da revogação desloca o risco para o mandante perante terceiros confiantes. O parágrafo protege poderes necessários a cumprir ou confirmar negócio ao qual ele já está vinculado.", "Cliente ignora revogação não divulgada e contrata de boa-fé com o antigo procurador; o ato pode ser oposto ao mandante.", "A proteção exige desconhecimento e boa-fé. Após ciência da revogação, o terceiro não pode invocar esta regra.", "Oponibilidade", "possibilidade de fazer uma alteração jurídica valer contra terceiros"),
    "687": row("A comunicação ao mandatário de que outra pessoa foi nomeada para o mesmo negócio revoga o mandato anterior.", "A substituição resulta da nomeação incompatível, mas o efeito depende de o antigo mandatário receber a comunicação.", "Proprietário informa ao primeiro procurador que nomeou outro para vender o mesmo bem; os poderes anteriores cessam.", "Nomeação para tarefa distinta não produz necessariamente esse efeito. Até a comunicação, devem ser consideradas a boa-fé e as demais regras do mandato.", "Revogação tácita", "retirada de poderes inferida de ato incompatível com a manutenção do mandato anterior"),
    "688": row("O mandatário que renuncia deve avisar o mandante. Se o momento ou a falta de prazo para substituição causar prejuízo, haverá indenização, salvo impossibilidade de continuar sem dano considerável e ausência de possibilidade de substabelecer.", "A liberdade de renunciar é acompanhada por dever de lealdade e transição. A exceção protege o mandatário diante de sacrifício grave inevitável.", "Procurador abandona negociação urgente sem aviso e impede substituição; responde pelo prejuízo provocado.", "A indenização não é automática: exige dano ligado à inoportunidade ou ao aviso insuficiente, além da análise conjunta das justificativas legais.", "Renúncia", "declaração do mandatário de que não continuará exercendo os poderes"),
    "689": row("Atos celebrados em nome do mandante com contratantes de boa-fé permanecem válidos enquanto o mandatário desconhecer a morte do mandante ou outra causa de extinção.", "A aparência legítima preserva o negócio quando nem o representante nem o terceiro conhecem o fim dos poderes.", "Mandatário ainda ignorando a morte do mandante conclui compra com vendedor de boa-fé; o ato recebe proteção legal.", "A regra exige ignorância do mandatário e boa-fé do contratante. Conhecimento da extinção afasta essa proteção, ressalvadas situações urgentes próprias.", "Aparência legítima", "situação exterior confiável que a lei protege em favor de quem age de boa-fé"),
    "690": row("Morrendo o mandatário com negócio pendente, seus herdeiros que souberem do mandato devem avisar o mandante e tomar as providências exigidas pelas circunstâncias para protegê-lo.", "Os herdeiros não assumem integralmente o mandato, mas têm dever transitório de comunicação e conservação para evitar perdas.", "Herdeiros encontram documentos de operação urgente, informam o mandante e preservam o prazo até que ele nomeie substituto.", "O dever pressupõe ciência do mandato. A extensão das providências é limitada pelo artigo seguinte e pela urgência concreta.", "Negócio pendente", "incumbência iniciada e ainda não concluída quando ocorre a morte"),
    "691": row("Os herdeiros do mandatário devem restringir-se a medidas de conservação ou continuar apenas negócios que não possam esperar sem risco, sujeitos, nesse limite, às regras aplicáveis ao mandatário.", "A atuação é emergencial e temporária. Ela protege o mandante sem converter os herdeiros em novos representantes gerais.", "Herdeiro protocola documento indispensável para evitar perda de direito, mas não inicia operação nova.", "Providências além da conservação ou da urgência não encontram autorização neste artigo. Os herdeiros respondem segundo as normas do mandato dentro da atuação permitida.", "Medida conservatória", "providência destinada a impedir perda ou deterioração de um direito"),
    "692": row("O mandato judicial segue prioritariamente a legislação processual e utiliza as regras civis do mandato apenas de forma suplementar.", "A procuração para atuar em processo possui poderes, formas, deveres e modos de extinção definidos pelo regime processual. O Código Civil preenche lacunas compatíveis.", "Para verificar se advogado pode receber citação ou fazer acordo, consulta-se primeiro a lei processual e o instrumento de procuração.", "Não se deve transportar automaticamente toda regra do mandato civil para a representação em juízo. A norma processual especial prevalece.", "Aplicação supletiva", "uso de uma regra para preencher lacuna deixada pelo regime principal"),
    "693": row("Na comissão, o comissário realiza compra, venda, mútuo ou outro negócio de crédito em nome próprio, mas por conta econômica do comitente.", "Diferentemente do mandatário que normalmente revela agir em nome alheio, o comissário aparece como parte perante terceiros. O resultado econômico pertence à relação interna com o comitente. A redação vigente desde 2023 inclui expressamente negócios de crédito.", "Instituição encarrega comissário de celebrar mútuo em nome dele, mas com recursos e resultado destinados ao comitente.", "Comissão não é simples representação: o comitente não aparece diretamente no contrato externo. Obrigações perante terceiros seguem o artigo seguinte.", "Comissário", "pessoa que contrata em nome próprio por conta de outra, chamada comitente"),
    "694": row("O comissário fica diretamente vinculado às pessoas com quem contrata; em regra, terceiros e comitente não têm ação direta entre si, salvo cessão dos direitos do comissário.", "Como o negócio externo é celebrado em nome próprio, o comissário ocupa a posição contratual. A relação econômica interna não cria automaticamente vínculo direto com o terceiro.", "Comissário compra mercadoria e responde ao vendedor; o comitente só poderá exercer direito externo se houver cessão adequada.", "A cessão transfere direitos, não apaga automaticamente obrigações nem dispensa requisitos próprios. A regra distingue comissão de mandato representativo.", "Cessão de direitos", "transferência de uma posição creditória para outra pessoa"),
    "695": row("O comissário deve cumprir ordens e instruções. Se elas faltarem e não puder consultá-las a tempo, segue os usos de negócios semelhantes. Atos úteis ao comitente ou urgentes e conformes aos usos podem ser justificados.", "A autonomia subsidiária existe para evitar paralisação, mas permanece orientada pelo interesse do comitente e pelas práticas pertinentes.", "Sem conseguir contato durante queda súbita de preço, comissário vende conforme o uso local para evitar perda maior.", "Vantagem posterior não legitima qualquer desobediência deliberada. Devem ser comprovadas urgência, impossibilidade de consulta ou utilidade prevista no parágrafo.", "Usos", "práticas reiteradas reconhecidas em determinado mercado ou tipo de negócio"),
    "696": row("O comissário deve atuar com cuidado para evitar prejuízo e buscar o lucro razoavelmente esperado. Responde por dano causado por ação ou omissão, salvo força maior.", "O dever combina diligência defensiva e atuação eficiente. A responsabilidade depende do comportamento danoso, enquanto evento inevitável pode afastá-la.", "Comissário deixa mercadoria perecível sem providência e indeniza a perda que poderia evitar.", "Lucro razoável não equivale a garantia de resultado. É preciso considerar instruções, condições do mercado, nexo causal e eventual força maior.", "Diligência", "cuidado e atuação ativa esperados de quem administra negócio alheio"),
    "697": row("Em regra, o comissário não garante a solvência das pessoas com quem negocia. Ele responde se agiu com culpa ou assumiu a garantia especial prevista no artigo seguinte.", "O risco normal de inadimplência do terceiro pertence ao comitente, pois o comissário não é fiador automático. Seleção negligente ou cláusula del credere mudam o resultado.", "Comprador escolhido com cautela torna-se insolvente depois; sem culpa nem garantia especial, o comissário não paga a dívida.", "Insolvência não se confunde com inadimplemento pontual. A culpa na escolha ou condução precisa ser examinada concretamente.", "Insolvência", "situação em que o patrimônio do devedor não basta para pagar suas obrigações"),
    "698": row("Com cláusula del credere, o comissário responde solidariamente com os terceiros contratados e, em regra, recebe remuneração maior pelo risco. Desde 2023, a garantia pode abranger apenas parte da operação.", "A cláusula transfere ao comissário total ou parcialmente o risco de inadimplência que normalmente seria do comitente. A solidariedade permite exigir dele a parcela garantida.", "Comissário garante metade do crédito concedido ao comprador e recebe comissão superior; se houver inadimplemento, responde dentro desse alcance.", "A garantia precisa constar do contrato e seu limite deve ser identificado. A remuneração maior pode ser afastada por estipulação contrária.", "Del credere", "cláusula pela qual o comissário garante a obrigação do terceiro, total ou parcialmente"),
    "699": row("Na ausência de instrução contrária, presume-se que o comissário pode conceder prazo de pagamento conforme os usos do lugar do negócio.", "A prática local completa o contrato e autoriza condições usuais de crédito sem consulta específica ao comitente.", "Em mercado onde vendas em trinta dias são usuais, o comissário concede esse prazo sem ordem expressa em sentido contrário.", "A presunção cede a instruções do comitente e depende de prova dos usos pertinentes. Prazo fora do padrão recebe o tratamento do artigo seguinte.", "Dilação", "ampliação ou concessão de prazo para cumprir uma obrigação"),
    "700": row("Se o comitente proibir prazo adicional, se a dilação contrariar os usos locais ou se faltar informação sobre prazo e beneficiário, ele pode exigir pagamento imediato do comissário ou responsabilizá-lo pelas consequências.", "O comissário assume o risco de concessão de crédito desautorizada, atípica ou não comunicada. A regra protege o controle do comitente sobre prazo e devedor.", "Apesar da ordem de vender à vista, comissário concede parcelamento; o comitente cobra dele imediatamente ou demonstra os prejuízos decorrentes.", "As alternativas e consequências dependem da violação ocorrida. Comunicação completa e conformidade com instruções e usos devem ser documentadas.", "Pagamento incontinenti", "pagamento exigível imediatamente, sem novo prazo"),
}
